# Generated by tools/pdmap (from-json export).

from tools.pdmap.builders import (
    add_loadout_intro,
    ctf_zones_from_mapdef,
    floor_box_with_ctf_zones,
)
from tools.pdmap.core import MapDef
from tools.pdmap.intro import Case, CaseRespawn, Spawn
from tools.pdmap import weapons as W

BOX_HALF = 2500.0
BOX_HEIGHT = 2000.0
SPAWN_Y = 10


def build() -> MapDef:
    g = MapDef("learn_08_ctf_case")

    # --- Pads (indices MUST match array order 0..N-1) ---
    g.add_pad(index=0, x=0.0, y=10, z=0.0, room=1)  # spawn
    g.add_pad(index=1, x=0.0, y=10, z=-500, room=1)  # scenario/case
    g.add_pad(index=2, x=0.0, y=10, z=500, room=1)  # scenario/case_respawn

    # --- Spawn intro commands ---
    g.add_intro(Spawn(pad=0))

    # --- Scenario anchors ---
    g.add_intro(Case(team=0, pad=1))
    g.add_intro(CaseRespawn(team=0, pad=2))

    add_loadout_intro(g)
    return g


def build_tiles_json():
    g = build()
    return floor_box_with_ctf_zones(
        "learn_08_ctf_case", half=BOX_HALF, y=0.0,
        zones=ctf_zones_from_mapdef(g),
    )
